package ru.voicereminder.app.reminders;
import android.Manifest;import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.speech.*;import android.speech.tts.TextToSpeech;import androidx.core.app.NotificationManagerCompat;import com.getcapacitor.*;import com.getcapacitor.annotation.*;import org.json.*;import java.util.*;
@CapacitorPlugin(name="ReminderEngine",permissions={@Permission(alias="microphone",strings={Manifest.permission.RECORD_AUDIO}),@Permission(alias="notifications",strings={Manifest.permission.POST_NOTIFICATIONS})})
public class ReminderPlugin extends Plugin {
 private SpeechRecognizer recognizer;private PluginCall recognition;private TextToSpeech preview;
 private String accumulated="";private String lastPartial="";private boolean stopping=false;private Intent recognitionIntent;private final Handler handler=new Handler(Looper.getMainLooper());

 @PluginMethod public void migrate(PluginCall call){try(ReminderStore db=new ReminderStore(getContext())){if(db.meta("migration").optBoolean("done")){getState(call);return;}JSONArray list=call.getArray("reminders",new JSArray());db.getWritableDatabase().beginTransaction();try{for(int i=0;i<list.length();i++){JSONObject r=list.getJSONObject(i);if(db.rule(r.getString("id"))!=null)continue;long next=ScheduleEngine.next(r.getJSONObject("schedule"),System.currentTimeMillis());r.put("nextTriggerAt",next>0?next:JSONObject.NULL);if(next<=0)r.put("enabled",false);db.put("rules","rid",r.getString("id"),r);}JSObject settings=call.getObject("settings");if(settings!=null&&db.meta("settings").length()==0)db.meta("settings",settings);db.meta("migration",new JSONObject().put("done",true));db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}AlarmScheduler.restore(getContext());call.resolve(JSObject.fromJSONObject(db.state()));}catch(Exception e){call.reject(e.getMessage());}}
 @Override protected void handleOnResume(){AlarmScheduler.restore(getContext());}
 @PluginMethod public void getBillingCredential(PluginCall call){try{call.resolve(new JSObject().put("token",SecretVault.get(getContext())));}catch(Exception e){call.reject("РќРµ СѓРґР°Р»РѕСЃСЊ РїСЂРѕС‡РёС‚Р°С‚СЊ РєР»СЋС‡ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ");}}
 @PluginMethod public void setBillingCredential(PluginCall call){try{SecretVault.set(getContext(),call.getString("token",""));call.resolve();}catch(Exception e){call.reject("РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕС…СЂР°РЅРёС‚СЊ РєР»СЋС‡ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ");}}
 @PluginMethod public void getState(PluginCall call){try(ReminderStore db=new ReminderStore(getContext())){call.resolve(JSObject.fromJSONObject(db.state()));}catch(Exception e){call.reject(e.getMessage());}}
 @PluginMethod public void settings(PluginCall call){try(ReminderStore db=new ReminderStore(getContext())){JSObject s=call.getObject("settings");if(s==null){call.reject("РќРµС‚ РЅР°СЃС‚СЂРѕРµРє");return;}db.meta("settings",s);call.resolve(JSObject.fromJSONObject(db.state()));}catch(Exception e){call.reject(e.getMessage());}}
 @PluginMethod public void upsert(PluginCall call){try(ReminderStore db=new ReminderStore(getContext())){JSObject r=call.getObject("reminder");if(r==null||r.optString("id").isEmpty()||r.optString("text").trim().isEmpty())throw new IllegalArgumentException("Р”РѕР±Р°РІСЊС‚Рµ С‚РµРєСЃС‚ РЅР°РїРѕРјРёРЅР°РЅРёСЏ");String id=r.getString("id");JSONObject previous=db.rule(id);long next=ScheduleEngine.next(r.getJSONObject("schedule"),System.currentTimeMillis());if(r.optBoolean("enabled",true)&&next<=0)throw new IllegalArgumentException("РќРµС‚ Р±СѓРґСѓС‰РёС… РґР°С‚");if(r.optBoolean("enabled",true)&&!AlarmScheduler.exact(getContext()))throw new IllegalArgumentException("Р Р°Р·СЂРµС€РёС‚Рµ С‚РѕС‡РЅС‹Рµ Р±СѓРґРёР»СЊРЅРёРєРё");if(r.optBoolean("enabled",true)&&!NotificationManagerCompat.from(getContext()).areNotificationsEnabled())throw new IllegalArgumentException("Р Р°Р·СЂРµС€РёС‚Рµ СѓРІРµРґРѕРјР»РµРЅРёСЏ РІ Android");JSONObject q=db.quota();boolean fresh=previous==null;
 db.getWritableDatabase().beginTransaction();try{AlarmScheduler.plan(getContext(),db,r);if(fresh){q.put("used",q.optInt("used")+1);db.meta("quota",q);}db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}call.resolve(JSObject.fromJSONObject(db.state()));}catch(Exception e){call.reject(e.getMessage());}}
 @PluginMethod public void remove(PluginCall call){try(ReminderStore db=new ReminderStore(getContext())){String id=call.getString("id");AlarmScheduler.cancel(getContext(),AlarmScheduler.FIRE,id);JSONArray events=db.all("events");for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if(e.optString("reminderId").equals(id))AlarmReceiver.ack(getContext(),db,e.getString("id"),"deleted");}db.removeRule(id);call.resolve(JSObject.fromJSONObject(db.state()));}catch(Exception e){call.reject(e.getMessage());}}
 @PluginMethod public void acknowledge(PluginCall call){try(ReminderStore db=new ReminderStore(getContext())){AlarmReceiver.ack(getContext(),db,call.getString("id"),call.getString("source","button"));call.resolve(JSObject.fromJSONObject(db.state()));}catch(Exception e){call.reject(e.getMessage());}}
 @PluginMethod public void snooze(PluginCall call){try(ReminderStore db=new ReminderStore(getContext())){AlarmReceiver.snooze(getContext(),db,call.getString("id"),call.getInt("minutes",5));call.resolve(JSObject.fromJSONObject(db.state()));}catch(Exception e){call.reject(e.getMessage());}}
 @PluginMethod public void permissions(PluginCall call){JSObject r=new JSObject();r.put("notifications",NotificationManagerCompat.from(getContext()).areNotificationsEnabled()?"granted":"denied");r.put("exact",AlarmScheduler.exact(getContext()));r.put("platform","android");call.resolve(r);}
 @PluginMethod public void requestPermissions(PluginCall call){if(Build.VERSION.SDK_INT>=33&&getPermissionState("notifications")!=PermissionState.GRANTED){requestPermissionForAlias("notifications",call,"notificationResult");return;}openExact(call);}
 @PermissionCallback private void notificationResult(PluginCall call){openExact(call);}
 private void openExact(PluginCall call){if(!NotificationManagerCompat.from(getContext()).areNotificationsEnabled()){permissions(call);return;}if(Build.VERSION.SDK_INT>=31&&!AlarmScheduler.exact(getContext()))getActivity().startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getContext().getPackageName())));permissions(call);}
 @PluginMethod public void speak(PluginCall call){String text=call.getString("text","");String language=call.getString("language","ru");getActivity().runOnUiThread(()->{if(preview!=null)preview.shutdown();preview=new TextToSpeech(getContext(),status->{if(status==TextToSpeech.SUCCESS){preview.setLanguage(language.equals("en")?Locale.US:new Locale("ru","RU"));preview.speak(text,TextToSpeech.QUEUE_FLUSH,null,"preview");call.resolve();}else call.reject("TTS РЅРµРґРѕСЃС‚СѓРїРµРЅ");});});}
 @PluginMethod public void recognize(PluginCall call){if(getPermissionState("microphone")!=PermissionState.GRANTED){requestPermissionForAlias("microphone",call,"microphoneResult");return;}startRecognition(call);}
 @PermissionCallback private void microphoneResult(PluginCall call){if(getPermissionState("microphone")!=PermissionState.GRANTED){call.reject("not-allowed");return;}startRecognition(call);}
 private void startRecognition(PluginCall call){getActivity().runOnUiThread(()->{if(recognition!=null){call.reject("Р—Р°РїРёСЃСЊ СѓР¶Рµ РёРґС‘С‚");return;}if(!SpeechRecognizer.isRecognitionAvailable(getContext())){call.reject("service-not-allowed");return;}recognition=call;accumulated="";stopping=false;recognitionIntent=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,call.getString("language","ru-RU")).putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true).putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,1).putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_COMPLETE_SILENCE_LENGTH_MILLIS,Integer.valueOf(60000)).putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_POSSIBLY_COMPLETE_SILENCE_LENGTH_MILLIS,Integer.valueOf(60000)).putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_MINIMUM_LENGTH_MILLIS,Integer.valueOf(2000));listen();});}
  // Одна сессия распознавания: тишина и паузы не перезапускают микрофон.
  // Пауза в речи закрывает системный распознаватель каждые несколько секунд.
  // Перезапускаем его незаметно: кнопка остаётся в состоянии "запись идёт"
  // до нажатия "Готово". При каждой попытке пересоздаём распознаватель и
  // на любой устранимой ошибке продолжаем, а не завершаем сессию.
  private void listen(){if(recognition==null)return;if(recognizer!=null){try{recognizer.destroy();}catch(Exception ignored){}recognizer=null;}
  recognizer=SpeechRecognizer.createSpeechRecognizer(getContext());recognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){}public void onBeginningOfSpeech(){}public void onRmsChanged(float x){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){if(recognition==null||stopping)return;resumeAfterPause();}
  public void onError(int code){if(recognition==null)return;if(code==SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS){PluginCall current=recognition;cleanup();if(current!=null)current.reject("not-allowed");return;}
  if(stopping){finishRecognition();return;}if(code==SpeechRecognizer.ERROR_NO_MATCH||code==SpeechRecognizer.ERROR_SPEECH_TIMEOUT||code==SpeechRecognizer.ERROR_RECOGNIZER_BUSY){resumeAfterPause();return;}
  resumeAfterPause();}
  public void onResults(Bundle b){ArrayList<String> matches=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(matches!=null&&!matches.isEmpty())append(matches.get(0));if(stopping){finishRecognition();return;}resumeAfterPause();}
  public void onPartialResults(Bundle b){ArrayList<String> matches=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(matches!=null&&!matches.isEmpty()){String t=matches.get(0);lastPartial=t;notifyListeners("recognitionPartial",new JSObject().put("text",(accumulated+(accumulated.isEmpty()?"":" ")+t).trim()));}}
  public void onEvent(int t,Bundle b){}});
  try{recognizer.startListening(recognitionIntent);}catch(Exception e){if(!stopping)resumeAfterPause();}}
  private void resumeAfterPause(){handler.postDelayed(()->{if(recognition!=null&&!stopping)listen();},340);}
  private void append(String part){String text=part==null?"":part.trim();if(text.isEmpty())return;if(accumulated.isEmpty())accumulated=text;else if(!accumulated.endsWith(text))accumulated=accumulated+" "+text;}
  private void finishRecognition(){String text=accumulated;if(text.isEmpty()&&lastPartial!=null&&!lastPartial.isEmpty())text=lastPartial.trim();PluginCall current=recognition;cleanup();if(current!=null)current.resolve(new JSObject().put("text",text));}
  private void cleanup(){recognition=null;stopping=false;if(recognizer!=null){try{recognizer.destroy();}catch(Exception ignored){}recognizer=null;}notifyListeners("recognitionState",new JSObject().put("status","stopped"));}
 @PluginMethod public void stopRecognition(PluginCall call){getActivity().runOnUiThread(()->{stopping=true;if(recognizer!=null){try{recognizer.stopListening();}catch(Exception ignored){}}handler.postDelayed(()->{if(recognition!=null)finishRecognition();},1200);call.resolve();});}
 @PluginMethod public void abortRecognition(PluginCall call){getActivity().runOnUiThread(()->{PluginCall pending=recognition;if(recognizer!=null){try{recognizer.cancel();}catch(Exception ignored){}}cleanup();if(pending!=null)pending.resolve(new JSObject().put("text",""));call.resolve();});}
 @Override protected void handleOnDestroy(){getActivity().runOnUiThread(()->{if(recognizer!=null)recognizer.destroy();if(preview!=null)preview.shutdown();});}
}
